      "quantityGood": quantityGood,
      "quantityScrap": quantityScrap,
      "occurAt": occurAt,
      "cycleTime": cycleTime,
      "source": source,
      "idealUnits": idealUnits,
      "performance": performance
    }
  } : []
}

