'use strict';

// ═══════════════════════════════════════════════════════════════════════
// PRODUCTION SIMULATOR - TIME-CONSTRAINED WITH HISTORY AWARENESS
// ═══════════════════════════════════════════════════════════════════════
// Generates simulated production records with realistic constraints:
// - Single random time window (0-10 minutes) applied to all workcenters
// - Round-robin workcenter assignment for unassigned work orders
// - Respects time since workcenter entered production mode
// - Respects time since last production log per work order
// - Processes oldest work orders first (by scheduledStartAt)
// - ISO 22400 performance calculation as decimal ratio
// ═══════════════════════════════════════════════════════════════════════

// Access data from payload
const workcenterHistoryEdges = $.workcenterHistory?.edges || [];
const workOrderEdges = $.workOrder?.edges || [];
const timezoneEdges = $.setting?.edges || [];

// Get tenant timezone
const tenantTimezone = timezoneEdges.length > 0 
  ? timezoneEdges[0].node.defaultValue 
  : 'America/New_York';

// Current time in tenant timezone
const nowLocal = $moment().tz(tenantTimezone);
const nowUtc = nowLocal.utc();

// ═══════════════════════════════════════════════════════════════════════
// GENERATE SINGLE RANDOM TIME WINDOW (0-10 MINUTES)
// ═══════════════════════════════════════════════════════════════════════
const minSeconds = 0;
const maxSeconds = 600;  // 10 minutes
const randomWindowSeconds = Math.floor(Math.random() * (maxSeconds - minSeconds + 1)) + minSeconds;

console.log('═══════════════════════════════════════════════════════════');
console.log('PRODUCTION SIMULATION - TIME-CONSTRAINED');
console.log('═══════════════════════════════════════════════════════════');
console.log('Random time window: ' + randomWindowSeconds + ' seconds (' + (randomWindowSeconds / 60).toFixed(2) + ' minutes)');
console.log('Tenant timezone: ' + tenantTimezone);
console.log('Current time: ' + nowLocal.format());
console.log('───────────────────────────────────────────────────────────');

// ═══════════════════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════════════════
const config = {
  defaultYield: 0.95,
  
  // Cycle time variability settings
  cycleTime: {
    minMultiplier: 0.70,
    maxMultiplier: 1.40,
    distribution: [
      { min: 0.70, max: 0.80, weight: 5 },
      { min: 0.80, max: 0.90, weight: 10 },
      { min: 0.90, max: 0.95, weight: 20 },
      { min: 0.95, max: 1.05, weight: 30 },
      { min: 1.05, max: 1.15, weight: 20 },
      { min: 1.15, max: 1.25, weight: 10 },
      { min: 1.25, max: 1.40, weight: 5 }
    ]
  }
};

// ═══════════════════════════════════════════════════════════════════════
// HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════

function generateProductionCode() {
  const timeComponent = $moment().tz(tenantTimezone).format('YYYYMMDDHHmmss');
  const randomComponent = Math.random().toString(36).substr(2, 5).toUpperCase();
  return 'PROD-' + timeComponent + '-' + randomComponent;
}

function getLocalTimestamp() {
  return $moment().tz(tenantTimezone).utc().toISOString();
}

function generatePerformanceMultiplier() {
  const distribution = config.cycleTime.distribution;
  const totalWeight = distribution.reduce((sum, bucket) => sum + bucket.weight, 0);
  let random = Math.random() * totalWeight;
  let selectedBucket = distribution[distribution.length - 1];
  
  for (const bucket of distribution) {
    random -= bucket.weight;
    if (random <= 0) {
      selectedBucket = bucket;
      break;
    }
  }
  
  const multiplier = selectedBucket.min + Math.random() * (selectedBucket.max - selectedBucket.min);
  return multiplier;
}

function getActualCycleTime(standardCycleTime) {
  const multiplier = generatePerformanceMultiplier();
  const actualCycleTime = standardCycleTime * multiplier;
  const performancePercent = (standardCycleTime / actualCycleTime) * 100;
  
  return {
    actualCycleTime: Math.round(actualCycleTime * 100) / 100,
    performanceMultiplier: Math.round(multiplier * 1000) / 1000,
    performancePercent: Math.round(performancePercent * 10) / 10
  };
}

function validateProductionData(workOrder, workcenterId) {
  const errors = [];
  
  if (!workcenterId) errors.push('Missing workcenterId');
  if (!workOrder.id) errors.push('Missing workOrder.id');
  if (!workOrder.productId) errors.push('Missing workOrder.productId');
  if (!workOrder.product) {
    errors.push('Missing workOrder.product');
  } else {
    if (!workOrder.product.standardCycleTime || workOrder.product.standardCycleTime <= 0) {
      errors.push('Invalid or missing product.standardCycleTime');
    }
  }
  if (!workOrder.quantityTarget || workOrder.quantityTarget <= 0) {
    errors.push('Invalid or missing quantityTarget');
  }
  
  return errors;
}

// ═══════════════════════════════════════════════════════════════════════
// EXTRACT PRODUCTION-CAPABLE WORKCENTERS
// ═══════════════════════════════════════════════════════════════════════
const productionWorkcenters = [];
const workcenterInfoMap = new Map();

workcenterHistoryEdges.forEach(edge => {
  const wch = edge?.node;
  if (!wch || !wch.workcenterId) return;
  
  // Only include if state indicates production capability
  if (wch.state?.isProducing !== true) {
    console.log(`Skipping workcenter ${wch.workcenterId}: not producing (state: ${wch.state?.code})`);
    return;
  }
  
  // Calculate time in production mode
  const modeStartTime = $moment(wch.occurAt);
  const timeInProductionSeconds = nowUtc.diff(modeStartTime, 'seconds');
  
  // Available time is minimum of random window and time in production mode
  const availableSeconds = Math.min(randomWindowSeconds, timeInProductionSeconds);
  
  if (availableSeconds <= 0) {
    console.log(`Skipping workcenter ${wch.workcenterId}: no available time (entered production ${timeInProductionSeconds}s ago)`);
    return;
  }
  
  productionWorkcenters.push(wch.workcenterId);
  workcenterInfoMap.set(wch.workcenterId, {
    historyId: wch.id,
    modeStartTime: modeStartTime,
    timeInProductionSeconds: timeInProductionSeconds,
    availableSeconds: availableSeconds,
    scheduleId: wch.scheduleId,
    stateCode: wch.state?.code || 'UNKNOWN',
    isProducing: wch.state?.isProducing || false
  });
  
  console.log(`Workcenter ${wch.workcenterId}: ${availableSeconds}s available (in production for ${timeInProductionSeconds}s, state: ${wch.state?.code})`);
});

console.log('───────────────────────────────────────────────────────────');
console.log('Production-capable workcenters: ' + productionWorkcenters.length);

if (productionWorkcenters.length === 0) {
  console.log('WARNING: No production-capable workcenters found. Exiting.');
  return {
    productionRecords: [],
    workOrderUpdates: [],
    summary: {
      timezone: tenantTimezone,
      executedAt: getLocalTimestamp(),
      randomWindowSeconds: randomWindowSeconds,
      error: 'No production-capable workcenters available'
    }
  };
}

// ═══════════════════════════════════════════════════════════════════════
// EXTRACT AND PREPARE WORK ORDERS
// ═══════════════════════════════════════════════════════════════════════
const allWorkOrders = [];
const invalidWorkOrders = [];

workOrderEdges.forEach((edge, index) => {
  const wo = edge?.node;
  if (!wo) {
    console.warn(`Skipping edge at index ${index}: no node found`);
    return;
  }
  
  allWorkOrders.push(wo);
});

console.log('Total work orders received: ' + allWorkOrders.length);

// ═══════════════════════════════════════════════════════════════════════
// ROUND-ROBIN WORKCENTER ASSIGNMENT
// ═══════════════════════════════════════════════════════════════════════
let roundRobinIndex = 0;
let assignedCount = 0;

allWorkOrders.forEach(wo => {
  if (!wo.workcenterId || wo.workcenterId === null) {
    wo.workcenterId = productionWorkcenters[roundRobinIndex];
    wo.wasAssigned = true;
    assignedCount++;
    roundRobinIndex = (roundRobinIndex + 1) % productionWorkcenters.length;
  } else {
    wo.wasAssigned = false;
  }
});

console.log('Work orders assigned to workcenters: ' + assignedCount);
console.log('───────────────────────────────────────────────────────────');

// ═══════════════════════════════════════════════════════════════════════
// SORT WORK ORDERS BY SCHEDULED START (OLDEST FIRST)
// ═══════════════════════════════════════════════════════════════════════
allWorkOrders.sort((a, b) => {
  const dateA = new Date(a.scheduledStartAt);
  const dateB = new Date(b.scheduledStartAt);
  return dateA - dateB;
});

console.log('Work orders sorted by scheduledStartAt (oldest first)');
console.log('Oldest WO: ' + allWorkOrders[0]?.code + ' (' + allWorkOrders[0]?.scheduledStartAt + ')');
console.log('Newest WO: ' + allWorkOrders[allWorkOrders.length - 1]?.code + ' (' + allWorkOrders[allWorkOrders.length - 1]?.scheduledStartAt + ')');
console.log('───────────────────────────────────────────────────────────');

// ═══════════════════════════════════════════════════════════════════════
// GROUP WORK ORDERS BY WORKCENTER
// ═══════════════════════════════════════════════════════════════════════
const workOrdersByWorkcenter = new Map();

allWorkOrders.forEach((wo, index) => {
  if (!wo.workcenterId) {
    invalidWorkOrders.push({
      index: index,
      workOrderId: wo.id,
      workOrderCode: wo.code,
      issue: 'NULL_WORKCENTER_ID',
      message: 'Work order has null workcenterId after assignment'
    });
    return;
  }
  
  if (!workOrdersByWorkcenter.has(wo.workcenterId)) {
    workOrdersByWorkcenter.set(wo.workcenterId, []);
  }
  workOrdersByWorkcenter.get(wo.workcenterId).push(wo);
});

console.log('Work orders grouped by workcenter: ' + workOrdersByWorkcenter.size + ' workcenters');
console.log('Invalid work orders: ' + invalidWorkOrders.length);
console.log('───────────────────────────────────────────────────────────');

// ═══════════════════════════════════════════════════════════════════════
// PROCESS RESULTS
// ═══════════════════════════════════════════════════════════════════════
const productionRecords = [];
const workOrderUpdates = [];
const validationIssues = [];

const performanceStats = {
  records: [],
  minPerformance: 1.0,
  maxPerformance: 1.0,
  totalPerformance: 0,
  minIso22400: 1.0,
  maxIso22400: 1.0,
  totalIso22400: 0,
  count: 0
};

// ═══════════════════════════════════════════════════════════════════════
// PROCESS EACH WORKCENTER
// ═══════════════════════════════════════════════════════════════════════
workOrdersByWorkcenter.forEach((workOrders, workcenterId) => {
  const wcInfo = workcenterInfoMap.get(workcenterId);
  
  if (!wcInfo) {
    console.log(`Skipping workcenter ${workcenterId}: not in production mode`);
    return;
  }
  
  let timeRemainingSeconds = wcInfo.availableSeconds;
  
  console.log(`\nProcessing workcenter ${workcenterId}:`);
  console.log(`  Available time: ${timeRemainingSeconds}s (${(timeRemainingSeconds / 60).toFixed(2)} min)`);
  console.log(`  Work orders: ${workOrders.length}`);
  console.log(`  State: ${wcInfo.stateCode}`);
  
  for (let woIndex = 0; woIndex < workOrders.length; woIndex++) {
    const workOrder = workOrders[woIndex];
    
    // ═══════════════════════════════════════════════════════════════════
    // VALIDATION
    // ═══════════════════════════════════════════════════════════════════
    const validationErrors = validateProductionData(workOrder, workcenterId);
    
    if (validationErrors.length > 0) {
      validationIssues.push({
        workcenterId: workcenterId,
        workOrderId: workOrder.id,
        workOrderCode: workOrder.code,
        issue: 'VALIDATION_FAILED',
        errors: validationErrors
      });
      console.log(`  ✗ WO ${workOrder.code}: Validation failed - ${validationErrors.join(', ')}`);
      continue;
    }
    
    // ═══════════════════════════════════════════════════════════════════
    // CHECK TIME SINCE LAST PRODUCTION
    // ═══════════════════════════════════════════════════════════════════
    let maxProductionTime = timeRemainingSeconds;
    
    if (workOrder.productionLogs && workOrder.productionLogs.total > 0) {
      // Has production logs - check time since last production
      const logs = workOrder.productionLogs.edges;
      if (logs && logs.length > 0) {
        // Find most recent log
        const sortedLogs = logs.slice().sort((a, b) => {
          return new Date(b.node.occurAt) - new Date(a.node.occurAt);
        });
        const lastLog = sortedLogs[0].node;
        const lastProductionTime = $moment(lastLog.occurAt);
        const timeSinceLastProduction = nowUtc.diff(lastProductionTime, 'seconds');
        
        // Cap production time by time since last production
        maxProductionTime = Math.min(maxProductionTime, timeSinceLastProduction);
        
        console.log(`  WO ${workOrder.code}: Last production ${timeSinceLastProduction}s ago, max time: ${maxProductionTime}s`);
      }
    } else {
      console.log(`  WO ${workOrder.code}: No production logs, max time: ${maxProductionTime}s`);
    }
    
    // Skip if no time available
    if (maxProductionTime <= 0) {
      console.log(`  ✗ WO ${workOrder.code}: No production time available`);
      continue;
    }
    
    // ═══════════════════════════════════════════════════════════════════
    // EXTRACT WORK ORDER DATA
    // ═══════════════════════════════════════════════════════════════════
    const { standardCycleTime, targetYield } = workOrder.product;
    const yieldDecimal = targetYield ? targetYield / 100 : config.defaultYield;
    
    const existingCompleted = workOrder.quantityCompleted || 0;
    const existingScrap = workOrder.quantityScrap || 0;
    const remainingGood = workOrder.quantityTarget - existingCompleted;
    
    // Skip if already complete
    if (remainingGood <= 0) {
      console.log(`  ✗ WO ${workOrder.code}: Already complete`);
      continue;
    }
    
    // ═══════════════════════════════════════════════════════════════════
    // GENERATE CYCLE TIME WITH VARIABILITY
    // ═══════════════════════════════════════════════════════════════════
    const cycleTimeResult = getActualCycleTime(standardCycleTime);
    const actualCycleTime = cycleTimeResult.actualCycleTime;
    
    // ═══════════════════════════════════════════════════════════════════
    // CALCULATE PRODUCTION QUANTITY
    // ═══════════════════════════════════════════════════════════════════
    const totalUnitsNeededToComplete = Math.ceil(remainingGood / yieldDecimal);
    const secondsNeededToComplete = totalUnitsNeededToComplete * actualCycleTime;
    
    let totalUnitsProduced, actualGood, actualScrap, newStatus;
    
    if (secondsNeededToComplete <= maxProductionTime) {
      // Can complete this work order
      totalUnitsProduced = totalUnitsNeededToComplete;
      actualGood = remainingGood;
      actualScrap = totalUnitsProduced - actualGood;
      newStatus = 'Completed';
    } else {
      // Partial production - use all available time
      totalUnitsProduced = Math.floor(maxProductionTime / actualCycleTime);
      actualGood = Math.floor(totalUnitsProduced * yieldDecimal);
      actualScrap = totalUnitsProduced - actualGood;
      newStatus = 'InProgress';
    }
    
    // Skip if can't produce at least 1 unit
    if (totalUnitsProduced < 1) {
      console.log(`  ✗ WO ${workOrder.code}: Insufficient time (need ${actualCycleTime}s, have ${maxProductionTime}s)`);
      break;
    }
    
    const cycleTime = totalUnitsProduced * actualCycleTime;
    
    // ═══════════════════════════════════════════════════════════════════
    // CALCULATE IDEAL UNITS AND ISO 22400 PERFORMANCE
    // ═══════════════════════════════════════════════════════════════════
    let idealCycleTimeMs;
    if (workOrder.product.idealCycleTime && workOrder.product.idealCycleTime > 0) {
      idealCycleTimeMs = workOrder.product.idealCycleTime;
    } else {
      idealCycleTimeMs = standardCycleTime * 1000;
    }
    
    const cycleTimeMs = cycleTime * 1000;
    const idealUnits = cycleTimeMs / idealCycleTimeMs;
    
    const actualOutput = totalUnitsProduced;
    const iso22400Performance = idealUnits > 0 ? actualOutput / idealUnits : 0;
    
    // Track performance stats
    performanceStats.records.push({
      workOrderCode: workOrder.code,
      standardCycleTime: standardCycleTime,
      actualCycleTime: actualCycleTime,
      performancePercent: cycleTimeResult.performancePercent,
      iso22400Performance: iso22400Performance
    });
    performanceStats.minPerformance = Math.min(performanceStats.minPerformance, cycleTimeResult.performancePercent);
    performanceStats.maxPerformance = Math.max(performanceStats.maxPerformance, cycleTimeResult.performancePercent);
    performanceStats.totalPerformance += cycleTimeResult.performancePercent;
    performanceStats.minIso22400 = Math.min(performanceStats.minIso22400, iso22400Performance);
    performanceStats.maxIso22400 = Math.max(performanceStats.maxIso22400, iso22400Performance);
    performanceStats.totalIso22400 += iso22400Performance;
    performanceStats.count++;
    
    // ═══════════════════════════════════════════════════════════════════
    // CREATE PRODUCTION RECORD
    // ═══════════════════════════════════════════════════════════════════
    const productionRecord = {
      code: generateProductionCode(),
      workcenterId: workcenterId,
      workOrderId: workOrder.id,
      workOrderCode: workOrder.code || 'UNKNOWN',
      productId: workOrder.productId,
      productCode: workOrder.product?.code || 'UNKNOWN',
      scheduleId: wcInfo.scheduleId,
      quantityGood: actualGood,
      quantityScrap: actualScrap,
      idealUnits: idealUnits,
      cycleTime: Math.round(cycleTime * 100) / 100,
      standardCycleTime: standardCycleTime * totalUnitsProduced,
      occurAt: getLocalTimestamp(),
      source: 'Integration',
      performanceMultiplier: cycleTimeResult.performanceMultiplier,
      performancePercent: cycleTimeResult.performancePercent,
      performance: Math.round(iso22400Performance * 10000) / 10000
    };
    
    // Final validation
    if (!productionRecord.workcenterId || !productionRecord.workOrderId || !productionRecord.productId) {
      console.log(`  ✗ WO ${workOrder.code}: Final validation failed`);
      validationIssues.push({
        workcenterId: workcenterId,
        workOrderId: workOrder.id,
        issue: 'FINAL_VALIDATION_FAILED',
        message: 'Production record has null required fields'
      });
      continue;
    }
    
    productionRecords.push(productionRecord);
    
    // ═══════════════════════════════════════════════════════════════════
    // CREATE WORK ORDER UPDATE
    // ═══════════════════════════════════════════════════════════════════
    const newCompleted = existingCompleted + actualGood;
    const newScrap = existingScrap + actualScrap;
    
    workOrderUpdates.push({
      id: workOrder.id,
      code: workOrder.code,
      wasAssigned: workOrder.wasAssigned,
      workcenterId: workcenterId,
      previousCompleted: existingCompleted,
      previousScrap: existingScrap,
      addedGood: actualGood,
      addedScrap: actualScrap,
      quantityCompleted: newCompleted,
      quantityScrap: newScrap,
      quantityTarget: workOrder.quantityTarget,
      status: newStatus
    });
    
    console.log(`  ✓ WO ${workOrder.code}: ${actualGood} good, ${actualScrap} scrap, ${(iso22400Performance * 100).toFixed(1)}% perf, ${newStatus}`);
    
    // Update remaining time
    timeRemainingSeconds -= cycleTime;
    
    // Move to next work order if completed
    if (newStatus === 'Completed') {
      // Continue to next work order
    } else {
      // Partial completion, this workcenter is done
      break;
    }
  }
});

// ═══════════════════════════════════════════════════════════════════════
// BUILD SUMMARY
// ═══════════════════════════════════════════════════════════════════════
const avgPerformance = performanceStats.count > 0 
  ? Math.round(performanceStats.totalPerformance / performanceStats.count * 10) / 10 
  : 100;

const avgIso22400 = performanceStats.count > 0 
  ? Math.round((performanceStats.totalIso22400 / performanceStats.count) * 10000) / 10000
  : 1.0;

const summary = {
  timezone: tenantTimezone,
  executedAt: getLocalTimestamp(),
  randomWindowSeconds: randomWindowSeconds,
  randomWindowMinutes: Math.round(randomWindowSeconds / 60 * 100) / 100,
  input: {
    workcenterHistoryTotal: workcenterHistoryEdges.length,
    productionCapableWorkcenters: productionWorkcenters.length,
    workOrdersTotal: allWorkOrders.length,
    workOrdersAssigned: assignedCount,
    workOrdersInvalid: invalidWorkOrders.length
  },
  output: {
    productionRecordsCreated: productionRecords.length,
    workOrdersUpdated: workOrderUpdates.length,
    workOrdersCompleted: workOrderUpdates.filter(wo => wo.status === 'Completed').length,
    totalGoodUnits: productionRecords.reduce((sum, r) => sum + r.quantityGood, 0),
    totalScrapUnits: productionRecords.reduce((sum, r) => sum + r.quantityScrap, 0),
    totalActualUnits: productionRecords.reduce((sum, r) => sum + r.quantityGood + r.quantityScrap, 0),
    totalIdealUnits: Math.round(productionRecords.reduce((sum, r) => sum + r.idealUnits, 0) * 100) / 100,
    totalCycleTimeSeconds: Math.round(productionRecords.reduce((sum, r) => sum + r.cycleTime, 0) * 100) / 100,
    totalStandardCycleTimeSeconds: productionRecords.reduce((sum, r) => sum + r.standardCycleTime, 0)
  },
  performance: {
    cycleTimeVariability: {
      minPerformancePercent: performanceStats.minPerformance,
      maxPerformancePercent: performanceStats.maxPerformance,
      avgPerformancePercent: avgPerformance
    },
    iso22400: {
      minPerformance: Math.round(performanceStats.minIso22400 * 10000) / 10000,
      maxPerformance: Math.round(performanceStats.maxIso22400 * 10000) / 10000,
      avgPerformance: avgIso22400
    },
    recordsWithVariability: performanceStats.count
  },
  validation: {
    invalidWorkOrders: invalidWorkOrders.length,
    validationIssues: validationIssues.length,
    totalIssues: invalidWorkOrders.length + validationIssues.length
  }
};

if (invalidWorkOrders.length > 0) {
  summary.invalidWorkOrders = invalidWorkOrders;
}

if (validationIssues.length > 0) {
  summary.validationIssues = validationIssues;
}

if (productionRecords.length === 0) {
  if (allWorkOrders.length === 0) {
    summary.zeroOutputReason = 'No work orders provided';
  } else if (productionWorkcenters.length === 0) {
    summary.zeroOutputReason = 'No production-capable workcenters available';
  } else if (randomWindowSeconds === 0) {
    summary.zeroOutputReason = 'Random time window is zero';
  } else {
    summary.zeroOutputReason = 'No production possible - check work order status, cycle times, and time constraints';
  }
